def write_files() -> int:
    """Write the complete RC4 bounded context."""

    count = 0
    for relative_path, content in FILES.items():
        destination = BASE_DIR / relative_path
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_text(content.strip() + "\n", encoding="utf-8")
        count += 1
    return count


def backup_existing() -> Path | None:
    """Create a timestamped backup of the current RC4 tree."""

    if not TARGET.exists():
        return None

    BACKUP_ROOT.mkdir(parents=True, exist_ok=True)
    backup = BACKUP_ROOT / datetime.now().strftime("%Y%m%d_%H%M%S")
    shutil.copytree(TARGET, backup)
    return backup


def recreate_tree() -> None:
    """Delete the existing RC4 tree and recreate it from scratch."""

    if TARGET.exists():
        shutil.rmtree(TARGET)

    TARGET.mkdir(parents=True, exist_ok=True)


def validate_collisions() -> None:
    """Fail if a Python module and package share the same name."""

    collision_names = {
        "models",
        "events",
        "permissions",
        "policies",
        "selectors",
        "services",
        "workflows",
        "validators",
    }
    for name in collision_names:
        module = TARGET / f"{name}.py"
        package = TARGET / name
        if module.exists() and package.is_dir():
            raise RuntimeError(f"Package collision detected: {module} and {package}")


def validate_ast() -> None:
    """Validate every generated Python file parses successfully."""

    for path in TARGET.rglob("*.py"):
        ast.parse(path.read_text(encoding="utf-8"), filename=str(path))


def validate_canonical_patient() -> None:
    """Ensure generated Python contains no legacy Patient imports."""

    legacy_prefix = "apps.clinical.patients"
    for path in TARGET.rglob("*.py"):
        module = ast.parse(
            path.read_text(encoding="utf-8"),
            filename=str(path),
        )
        for node in ast.walk(module):
            if isinstance(node, ast.Import):
                for alias in node.names:
                    if alias.name.startswith(legacy_prefix):
                        raise RuntimeError(f"Legacy Patient import found: {path}")
            elif isinstance(node, ast.ImportFrom):
                module_name = node.module or ""
                if module_name.startswith(legacy_prefix):
                    raise RuntimeError(f"Legacy Patient import found: {path}")


def main() -> None:
    """Execute the complete RC4 rebuild."""

    print("=" * 78)
    print("DatavionAI Revenue Cycle RC4 Charge Capture Complete Rebuild Installer")
    print("=" * 78)

    backup = backup_existing()
    if backup:
        print(f"BACKUP CREATED: {backup}")
    else:
        print("BACKUP: NOT REQUIRED")

    recreate_tree()
    count = write_files()

    validate_collisions()
    validate_ast()
    validate_canonical_patient()

    compiled = compileall.compile_dir(
        str(TARGET),
        quiet=1,
        force=True,
    )
    if not compiled:
        raise RuntimeError("PY_COMPILE: FAIL")

    print("COMPLETE TREE RECREATED: PASS")
    print("PACKAGE COLLISIONS: NONE")
    print("AST VALIDATION: PASS")
    print("PY_COMPILE: PASS")
    print(f"FILES WRITTEN: {count}")
    print("MIGRATIONS NOT GENERATED")
    print("DATABASE NOT MODIFIED")
    print("LEGACY PATIENT MODULE NOT MODIFIED")
    print("RC4 CHARGE CAPTURE COMPLETE REBUILD: PASS")


if __name__ == "__main__":
    main()
